SELECT
    COUNT(*) AS CNT
FROM TB_BMS_ABNORMAL
WHERE 1 = 1
  AND MBL_NO = #{mblNo}

  AND AR_DATE = #{arDate}

SELECT AA.* , COUNT(*) OVER() AS TOTAL_CNT FROM ( SELECT BL_NO , MBL_NO , OD_JOB_NO , CARGO_REFERENCE_NO , SUBSTRING(CARGO_REFERENCE_NO,16,4) AS HSN , PKG_TYPE , EX_CT , EX_WT , IN_PLAN_NO , CONSIGNEE_NAME , COMMODITY_ITEM_LOC FROM TB_BMS_IN_PLAN WITH (NOLOCK) WHERE 1 =1 AND MBL_NO = #{mblNo} AND AR_DATE = #{arDate}
AND BL_NO NOT IN (#{item})
) AA

SELECT AA.* , COUNT(*) OVER() AS TOTAL_CNT FROM ( SELECT BL_NO , MBL_NO , CARGO_REFERENCE_NO , SUBSTRING(CARGO_REFERENCE_NO,16,4) AS HSN , PKG_TYPE , EX_CT , EX_WT , IN_PLAN_NO , CONSIGNEE_NAME , COMMODITY_ITEM_LOC FROM TB_BMS_IN_PLAN WITH (NOLOCK) WHERE 1 =1 AND MBL_NO = #{mblNo} AND AR_DATE = #{arDate}
