INSERT INTO TB_BMS_ABNORMAL (
          LAST_POD_STATUS
        , CUSTOMS_REPORT_NO
        , MRN
        , MSN
        , MBL_NO
        , VESSEL_FLIGHT
        , AR_DATE
        , AR_TIME
        , ABN_REQ_DATE
        , REGISTER_USER_ID
        , REGISTER_DATE_TIME
        , UPDATE_USER_ID
        , UPDATE_DATE_TIME )
VALUES (
        'BMS01'
       , #{customsReportNo}
       , #{mrn}
       , #{msn}
       , #{mblNo}
       , #{vesselFlight}
       , #{arDate}
       , #{arTime}
       , #{abnReqDate}
       , #{registerUserId}
       , GETDATE()
       , #{updateUserId}
       , GETDATE()
       )

INSERT INTO TB_BMS_ABNORMAL_BL(
         ABN_NO
       , SEQ_NO
       , CARGO_REFERENCE_NO
       , HSN
       , BL_NO
       , PKG_TYPE
       , EX_CT
       , EX_WT
       , CT
       , WT
       , ACCIDENT_CLASS
       , ACCIDENT_CT
       , ACCIDENT_WT
       , REJECT_REASON
       , REGISTER_USER_ID
       , REGISTER_DATE_TIME
       , UPDATE_USER_ID
       , UPDATE_DATE_TIME
)
VALUES (
         #{abnNo}
       , (SELECT ISNULL(MAX(SEQ_NO),0) + 1 FROM TB_BMS_ABNORMAL_BL WHERE ABN_NO = #{abnNo})
       , #{cargoReferenceNo}
       , #{hsn}
       , #{blNo}
       , #{pkgType}
       , #{exCt}
       , #{exWt}
       , #{ct}
       , #{wt}
       , #{accidentClass}
       , #{accidentCt}
       , #{accidentWt}
       , #{rejectReason}
       , #{registerUserId}
       , GETDATE()
       , #{updateUserId}
       , GETDATE()
)

